type Session = { role: "member" | "admin" } | null;
type CheckoutDecision = "allow" | "login" | "catalog";

function canEnterCheckout(session: Session, itemCount: number): CheckoutDecision {
  if (session === null) {
    return "login";
  }
  if (itemCount <= 0) {
    return "catalog";
  }
  return "allow";
}
